// Function example that uses parameters and returns a result

function greet(name) {

  // The code inside runs only when the function is called
  return "Hello, " + name + "! Welcome to JavaScript.";
}

// Calling the function
console.log(greet("Taylor")); 
// Output: Hello, Taylor! Welcome to JavaScript.

// use: great for reusing code that performs one specific task

Example:

// Example of conditional statements
function compareNumbers(a, b) {
  if (a < b) {
    console.log("a is less than b");
  } else if (a == b) {
    console.log("a equals b");
  } else {
    console.log("a is greater than b");
  }
}

compareNumbers(5, 10); // Output: a is less than b
// use: helpful when deciding what action to take in a program

