let cars = ["Saab", "Volvo", "BMW"];
	//The array’s name is cars.
	//It has three values: "Saab", "Volvo", and "BMW".

// Accessing Array Elements
console.log(cars[0]); // Output: Saab

// Changing an Array Element
cars[0] = "Toyota";
console.log(cars);
// Output: ["Toyota", "Volvo", "BMW"]

 // Array Length
