Example: // Example object with properties and a method

let car = {
  type: "Sedan",
  model: "Honda Civic",
  color: "Black",
  start: function() {
    console.log("The car is starting...");
  }
};

console.log(car.model); // Access value → "Honda Civic"
car.start(); // Calls method → "The car is starting..."
// use: organize data for real-world things like cars, students, or users

