// Example: A class that represents a Rectangle

class Rectangle {
  constructor(width, height) {

    // constructor sets initial values

    this.width = width;
    this.height = height;
  }

  get area() {

    // getter calculates area when called
    return this.width * this.height;
  }
}

// create an object (instance) from the class

const rect = new Rectangle(5, 10);
console.log(rect.area); // Output: 50

// use: easily create many rectangles with same structure

