// File: mathTools.js

export function add(a, b) {

  // export makes this function available in other files

  return a + b;
}

// File: main.js

import { add } from './mathTools.js'; 

// import brings in the function from another file

console.log(add(2, 3)); // Output: 5

// use: organize reusable functions or classes in separate files

