let globalVar = "I’m global"; // global scope — can be used anywhere

function showScope() {
  let localVar = "I’m local"; // local scope — works only inside function
  if (true) {
    let blockVar = "I’m block-scoped"; // block scope — only inside this block
    console.log(blockVar);
  }
  console.log(localVar);
}

showScope();
console.log(globalVar);
// use: control variable visibility to avoid conflicts

